export const GUIDED: Record<string, GuidedLab> = {"labex-sklearn-evaluating-machine-learning-model-quality":{"intro":"In machine learning, it is important to evaluate the quality of the predictions made by a model. This helps us understand how well the model is performing and whether it can be trusted for making accurate predictions. The scikit-learn library provides several metrics and scoring methods to quantify the quality of predictions.","steps":[{"title":"Estimator Score Method","body":["The Estimator score method is a default evaluation criterion provided by scikit-learn for each estimator. It calculates a score that represents the quality of the model's predictions. You can find more information about this in the documentation of each estimator.","Here's an example of using the score method for an estimator:"],"code":[{"lang":"python","text":"from sklearn.linear_model import LogisticRegression\nfrom sklearn.datasets import load_digits\n\nX, y = load_digits(return_X_y=True)\nclf = LogisticRegression()\nclf.fit(X, y)\n\nscore = clf.score(X, y)\nprint(\"Score:\", score)"}]},{"title":"Scoring Parameter","body":["Scikit-learn provides a scoring parameter in several model evaluation tools, such as cross-validation and grid search. The scoring parameter controls the metric applied to the estimators during evaluation.","Here's an example of using the scoring parameter with cross-validation:"],"code":[{"lang":"python","text":"from sklearn.model_selection import cross_val_score\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.datasets import load_digits\n\nX, y = load_digits(return_X_y=True)\nclf = LogisticRegression()\n\nscores = cross_val_score(clf, X, y, cv=5, scoring='accuracy')\nprint(\"Scores:\", scores)"}]},{"title":"Metric Functions","body":["The scikit-learn metrics module implements several functions for assessing prediction error for specific purposes. These functions can be used to calculate the quality of predictions made by a model.","Here's an example of using the accuracy_score function from the metrics module:"],"code":[{"lang":"python","text":"from sklearn.metrics import accuracy_score\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.datasets import load_digits\nfrom sklearn.model_selection import train_test_split\n\nX, y = load_digits(return_X_y=True)\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2)\n\nclf = LogisticRegression()\nclf.fit(X_train, y_train)\n\ny_pred = clf.predict(X_test)\naccuracy = accuracy_score(y_test, y_pred)\nprint(\"Accuracy:\", accuracy)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from sklearn.metrics import accuracy_score\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.datasets import load_digits\nfrom sklearn.model_selection import train_test_split\n\nX, y = load_digits(return_X_y=True)\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2)\n\nclf = LogisticRegression()\nclf.fit(X_train, y_train)\n\ny_pred = clf.predict(X_test)\naccuracy = accuracy_score(y_test, y_pred)\nprint(\"Accuracy:\", accuracy)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-validation-curves-plotting-scores-to-evaluat":{"intro":"In machine learning, every estimator has its advantages and drawbacks. The generalization error of an estimator can be decomposed into bias, variance, and noise. The bias of an estimator is the average error for different training sets, while the variance indicates its sensitivity to varying training sets. Noise is a property of the data.","steps":[{"title":"Import the Required Libraries and Load the Data","body":["Import the Required Libraries and Load the Data","Let's start by importing the necessary libraries and loading a dataset. In this example, we will use the Iris dataset."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.model_selection import validation_curve\nfrom sklearn.datasets import load_iris\nfrom sklearn.linear_model import Ridge\n\nnp.random.seed(0)\nX, y = load_iris(return_X_y=True)"}]},{"title":"Shuffle the Data","body":["To ensure randomness in our analysis, let's shuffle the order of the samples in our dataset."],"code":[{"lang":"python","text":"indices = np.arange(y.shape[0])\nnp.random.shuffle(indices)\nX, y = X[indices], y[indices]"}]},{"title":"Plot the Validation Curve","body":["Now, let's plot the validation curve using the validation_curve function. We will use the Ridge estimator and vary the alpha hyperparameter over a range of values."],"code":[{"lang":"python","text":"param_range = np.logspace(-7, 3, 3)\ntrain_scores, valid_scores = validation_curve(\n    Ridge(), X, y, param_name=\"alpha\", param_range=param_range, cv=5)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"param_range = np.logspace(-7, 3, 3)\ntrain_scores, valid_scores = validation_curve(\n    Ridge(), X, y, param_name=\"alpha\", param_range=param_range, cv=5)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-partial-dependence-and-individual-conditiona":{"intro":"Partial dependence plots (PDP) and individual conditional expectation (ICE) plots are useful tools for visualizing and analyzing the interaction between the target response and a set of input features. PDPs show the dependence between the target response and the input features, while ICE plots visualize the dependence of the prediction on a feature for each individual sample. These plots help us understand the relationship between the target response and the input features.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries"],"code":[{"lang":"python","text":"import numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom sklearn.datasets import load_boston\nfrom sklearn.ensemble import RandomForestRegressor\nfrom sklearn.inspection import plot_partial_dependence, partial_dependence"}]},{"title":"Load and prepare the data","body":[],"code":[{"lang":"python","text":"data = load_boston()\nX = data.data\ny = data.target\nfeature_names = data.feature_names\n\n# Create a DataFrame for easier data manipulation\ndf = pd.DataFrame(X, columns=feature_names)"}]},{"title":"Train a Random Forest model","body":[],"code":[{"lang":"python","text":"model = RandomForestRegressor()\nmodel.fit(X, y)"}]},{"title":"Create and visualize partial dependence plots","body":["Create and visualize partial dependence plots"],"code":[{"lang":"python","text":"fig, ax = plot_partial_dependence(model, X, features=[(0, 1), (2, 3)], feature_names=feature_names, grid_resolution=20)\n\n# Set figure size and title\nfig.set_size_inches(10, 8)\nfig.suptitle('Partial Dependence Plots')\n\nplt.show()"}]},{"title":"Create and visualize individual conditional expectation plots","body":["Create and visualize individual conditional expectation plots"],"code":[{"lang":"python","text":"fig, ax = plot_partial_dependence(model, X, features=[(0, 1), (2, 3)], feature_names=feature_names, kind='individual')\n\n# Set figure size and title\nfig.set_size_inches(10, 8)\nfig.suptitle('Individual Conditional Expectation Plots')\n\nplt.show()"}]},{"title":"Compute partial dependence values for a specific feature","body":["Compute partial dependence values for a specific feature"],"code":[{"lang":"python","text":"x_index = 0\npdp, axes = partial_dependence(model, X, features=[x_index], grid_resolution=20)\n\n# Plot the partial dependence values\nplt.plot(axes[x_index], pdp[0])\nplt.xlabel(feature_names[x_index])\nplt.ylabel(\"Partial Dependence\")\nplt.title(\"Partial Dependence Plot\")\n\nplt.show()"}]},{"title":"Compute individual conditional expectation values for a specific feature","body":["Compute individual conditional expectation values for a specific feature"],"code":[{"lang":"python","text":"x_index = 0\nice, axes = partial_dependence(model, X, features=[x_index], kind='individual')\n\n# Plot the individual conditional expectation values\nfor i in range(len(ice)):\n    plt.plot(axes[x_index], ice[i], color='lightgray')\nplt.plot(axes[x_index], np.mean(ice, axis=0), color='blue')\nplt.xlabel(feature_names[x_index])\nplt.ylabel(\"Individual Conditional Expectation\")\nplt.title(\"Individual Conditional Expectation Plot\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"x_index = 0\nice, axes = partial_dependence(model, X, features=[x_index], kind='individual')\n\n# Plot the individual conditional expectation values\nfor i in range(len(ice)):\n    plt.plot(axes[x_index], ice[i], color='lightgray')\nplt.plot(axes[x_index], np.mean(ice, axis=0), color='blue')\nplt.xlabel(feature_names[x_index])\nplt.ylabel(\"Individual Conditional Expectation\")\nplt.title(\"Individual Conditional Expectation Plot\")\n\nplt.show()"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-permutation-feature-importance":{"intro":"In this lab, we will learn about the Permutation Feature Importance method, which is a model inspection technique used to determine the importance of features in a predictive model. This technique can be especially useful for non-linear or opaque models that are difficult to interpret.","steps":[{"title":"Load the dataset","body":["First, we need to load a dataset that we can use to train our predictive model. We will use the Diabetes dataset from scikit-learn, which contains information about diabetes patients."],"code":[{"lang":"python","text":"from sklearn.datasets import load_diabetes\n\n# Load the Diabetes dataset\ndiabetes = load_diabetes()\n\n# Split the data into training and validation sets\nX_train, X_val, y_train, y_val = train_test_split(diabetes.data, diabetes.target, random_state=0)"}]},{"title":"Train the model","body":["Next, we will train a regression model on the training data. In this example, we will use a Ridge regression model."],"code":[{"lang":"python","text":"from sklearn.linear_model import Ridge\n\n# Train the Ridge regression model\nmodel = Ridge(alpha=1e-2).fit(X_train, y_train)"}]},{"title":"Evaluate the model","body":["We will now evaluate the trained model using the validation set. The evaluation metric used here is the R-squared score."],"code":[{"lang":"python","text":"# Evaluate the model on the validation set\nscore = model.score(X_val, y_val)\nprint(\"Validation score:\", score)"}]},{"title":"Calculate permutation feature importance","body":["Calculate permutation feature importance","Now, we will calculate the permutation feature importance using the permutation_importance function from scikit-learn. This function takes as input the trained model, the validation set, and the number of times the features should be permuted."],"code":[{"lang":"python","text":"from sklearn.inspection import permutation_importance\n\n# Calculate permutation feature importance\nresult = permutation_importance(model, X_val, y_val, n_repeats=30, random_state=0)\n\n# Print the feature importances\nfor i in result.importances_mean.argsort()[::-1]:\n    if result.importances_mean[i] - 2 * result.importances_std[i] > 0:\n        print(f\"{diabetes.feature_names[i]}: {result.importances_mean[i]:.3f} +/- {result.importances_std[i]:.3f}\")"}]},{"title":"Interpret the results","body":["The calculated feature importances represent the decrease in the model score when a single feature value is randomly shuffled. Features with a higher importance value indicate that the model relies more heavily on those features for its predictions.","In this example, the top features that contribute the most to the model's performance are \"s5\", \"bmi\", \"bp\", and \"sex\"."],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-pipelines-and-composite-estimators":{"intro":"In scikit-learn, pipelines and composite estimators are used to combine multiple transformers and estimators into a single model. This is useful when there is a fixed sequence of steps for processing the data, such as feature selection, normalization, and classification. Pipelines can also be used for joint parameter selection and to ensure that statistics from the test data do not leak into the trained model during cross-validation.","steps":[{"title":"Pipeline - Chaining Estimators","body":["Pipeline - Chaining Estimators","The Pipeline class in scikit-learn is used to chain multiple estimators into one. This allows you to call fit and predict once on your data to fit a whole sequence of estimators. It also allows for joint parameter selection and helps avoid data leakage in cross-validation.","To create a pipeline, you need to provide a list of (key, value) pairs, where the key is a string to identify each step and the value is an estimator object. Below is an example of creating a pipeline with a PCA transformer and an SVM classifier:","You can access the steps of a pipeline using indexing or by name:"],"code":[{"lang":"python","text":"from sklearn.pipeline import Pipeline\nfrom sklearn.svm import SVC\nfrom sklearn.decomposition import PCA\n\nestimators = [('reduce_dim', PCA()), ('clf', SVC())]\npipe = Pipeline(estimators)"},{"lang":"python","text":"pipe.steps[0]  # access by index\npipe[0]  # equivalent to above\npipe['reduce_dim']  # access by name"},{"lang":"python","text":"from sklearn.pipeline import make_pipeline\nfrom sklearn.naive_bayes import MultinomialNB\nfrom sklearn.preprocessing import Binarizer\n\nmake_pipeline(Binarizer(), MultinomialNB())"}]},{"title":"Nested Parameters","body":["You can access the parameters of the estimators in a pipeline using the syntax <estimator>__<parameter>. This is useful for doing grid searches over the parameters of all estimators in the pipeline. Here is an example:"],"code":[{"lang":"python","text":"pipe.set_params(clf__C=10)"}]},{"title":"Caching Transformers","body":["Fitting transformers can be computationally expensive. To avoid repeated computation, you can enable caching transformers in a pipeline using the memory parameter. This parameter can be set to a directory where the transformers will be cached, or to a joblib.Memory object. Here is an example:"],"code":[{"lang":"python","text":"from sklearn.decomposition import PCA\nfrom sklearn.svm import SVC\nfrom sklearn.pipeline import Pipeline\nfrom tempfile import mkdtemp\nfrom shutil import rmtree\n\nestimators = [('reduce_dim', PCA()), ('clf', SVC())]\ncachedir = mkdtemp()\npipe = Pipeline(estimators, memory=cachedir)\n\n# Clear the cache directory when no longer needed\nrmtree(cachedir)"}]},{"title":"TransformedTargetRegressor","body":["The TransformedTargetRegressor class is used to transform the target variable in a regression problem before fitting a regression model. This is useful when you want to apply a transformation to the target variable, such as taking the logarithm. The predictions are mapped back to the original space via an inverse transform. Here is an example of using TransformedTargetRegressor with a linear regression model and a quantile transformer:"],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.datasets import fetch_california_housing\nfrom sklearn.compose import TransformedTargetRegressor\nfrom sklearn.preprocessing import QuantileTransformer\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.model_selection import train_test_split\n\nX, y = fetch_california_housing(return_X_y=True)\ntransformer = QuantileTransformer(output_distribution='normal')\nregressor = LinearRegression()\nregr = TransformedTargetRegressor(regressor=regressor, transformer=transformer)\nX_train, X_test, y_train, y_test = train_test_split(X, y, random_state=0)\nregr.fit(X_train, y_train)\nregr.score(X_test, y_test)"}]},{"title":"FeatureUnion - Composite Feature Spaces","body":["FeatureUnion - Composite Feature Spaces","The FeatureUnion class is used to combine multiple transformer objects into a new transformer that combines their output. This is useful when you want to apply different transformations to different features of the data, such as preprocessing text, floats, and dates separately. The transformers are applied in parallel, and the feature matrices they output are concatenated side-by-side into a larger matrix. Here is an example:"],"code":[{"lang":"python","text":"from sklearn.pipeline import FeatureUnion\nfrom sklearn.decomposition import PCA\nfrom sklearn.decomposition import KernelPCA\n\nestimators = [('linear_pca', PCA()), ('kernel_pca', KernelPCA())]\ncombined = FeatureUnion(estimators)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from sklearn.pipeline import FeatureUnion\nfrom sklearn.decomposition import PCA\nfrom sklearn.decomposition import KernelPCA\n\nestimators = [('linear_pca', PCA()), ('kernel_pca', KernelPCA())]\ncombined = FeatureUnion(estimators)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-feature-extraction-with-scikit-learn":{"intro":"In this lab, we will learn how to perform feature extraction using the scikit-learn library. Feature extraction is the process of transforming raw data into numerical features that can be used by machine learning algorithms. It involves extracting relevant information from different types of data such as text and images.","steps":[{"title":"Loading features from dicts","body":["In this step, we will learn how to load features from dictionaries using the DictVectorizer class in scikit-learn."],"code":[{"lang":"python","text":"from sklearn.feature_extraction import DictVectorizer\n\nmeasurements = [\n    {'city': 'Dubai', 'temperature': 33.},\n    {'city': 'London', 'temperature': 12.},\n    {'city': 'San Francisco', 'temperature': 18.},\n]\n\nvec = DictVectorizer()\nfeatures = vec.fit_transform(measurements).toarray()\nfeature_names = vec.get_feature_names_out()\n\nprint(features)\nprint(feature_names)"}]},{"title":"Feature hashing","body":["In this step, we will learn how to perform feature hashing using the FeatureHasher class in scikit-learn. Feature hashing is a technique that maps features to a fixed-length vector using a hash function."],"code":[{"lang":"python","text":"from sklearn.feature_extraction import FeatureHasher\n\nmovies = [\n    {'category': ['thriller', 'drama'], 'year': 2003},\n    {'category': ['animation', 'family'], 'year': 2011},\n    {'year': 1974},\n]\n\nhasher = FeatureHasher(input_type='string')\nhashed_features = hasher.transform(movies).toarray()\n\nprint(hashed_features)"}]},{"title":"Text feature extraction","body":["In this step, we will learn how to perform text feature extraction using the CountVectorizer and TfidfVectorizer classes in scikit-learn. These classes can be used to convert text data into numerical features."],"code":[{"lang":"python","text":"from sklearn.feature_extraction.text import CountVectorizer\n\ncorpus = [\n    'This is the first document.',\n    'This is the second second document.',\n    'And the third one.',\n    'Is this the first document?',\n]\n\nvectorizer = CountVectorizer()\nfeatures = vectorizer.fit_transform(corpus).toarray()\nfeature_names = vectorizer.get_feature_names_out()\n\nprint(features)\nprint(feature_names)"}]},{"title":"Customizing the vectorizer classes","body":["Customizing the vectorizer classes","In this step, we will learn how to customize the behavior of vectorizer classes by passing callable functions to them."],"code":[{"lang":"python","text":"def my_tokenizer(s):\n    return s.split()\n\nvectorizer = CountVectorizer(tokenizer=my_tokenizer)\nfeatures = vectorizer.fit_transform(corpus).toarray()\n\nprint(features)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"def my_tokenizer(s):\n    return s.split()\n\nvectorizer = CountVectorizer(tokenizer=my_tokenizer)\nfeatures = vectorizer.fit_transform(corpus).toarray()\n\nprint(features)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-preprocessing-techniques-in-scikit-learn":{"intro":"In this lab, we will explore the preprocessing techniques available in scikit-learn. Preprocessing is an essential step in any machine learning workflow as it helps to transform raw data into a suitable format for the learning algorithm. We will cover various preprocessing techniques such as standardization, scaling, normalization, encoding categorical features, imputing missing values, generating polynomial features, and creating custom transformers.","steps":[{"title":"Standardization","body":["Standardization is a common preprocessing step for many machine learning algorithms. It transforms features to have zero mean and unit variance. We can use the StandardScaler from scikit-learn to perform standardization."],"code":[{"lang":"python","text":"from sklearn.preprocessing import StandardScaler\nimport numpy as np\n\n# Create a sample dataset\nX = np.array([[1., -1., 2.],\n              [2., 0., 0.],\n              [0., 1., -1.]])\n\n# Initialize the StandardScaler\nscaler = StandardScaler()\n\n# Fit the scaler on the training data\nscaler.fit(X)\n\n# Transform the training data\nX_scaled = scaler.transform(X)\n\n# Print the transformed data\nprint(X_scaled)"}]},{"title":"Scaling","body":["Scaling features to a specific range is another common preprocessing technique. It is useful when features have different scales and we want to bring them all to a similar range. The MinMaxScaler and MaxAbsScaler can be used to perform scaling."],"code":[{"lang":"python","text":"from sklearn.preprocessing import MinMaxScaler, MaxAbsScaler\nimport numpy as np\n\n# Create a sample dataset\nX = np.array([[1., -1., 2.],\n              [2., 0., 0.],\n              [0., 1., -1.]])\n\n# Initialize the MinMaxScaler\nmin_max_scaler = MinMaxScaler()\n\n# Fit and transform the training data\nX_minmax = min_max_scaler.fit_transform(X)\n\n# Print the transformed data\nprint(X_minmax)\n\n# Initialize the MaxAbsScaler\nmax_abs_scaler = MaxAbsScaler()\n\n# Fit and transform the training data\nX_maxabs = max_abs_scaler.fit_transform(X)\n\n# Print the transformed data\nprint(X_maxabs)"}]},{"title":"Normalization","body":["Normalization is the process of scaling individual samples to have unit norm. It is commonly used when the magnitude of the data is not important and we are only interested in the direction (or angle) of the data. We can use the Normalizer from scikit-learn to perform normalization."],"code":[{"lang":"python","text":"from sklearn.preprocessing import Normalizer\nimport numpy as np\n\n# Create a sample dataset\nX = np.array([[1., -1., 2.],\n              [2., 0., 0.],\n              [0., 1., -1.]])\n\n# Initialize the Normalizer\nnormalizer = Normalizer()\n\n# Fit and transform the training data\nX_normalized = normalizer.fit_transform(X)\n\n# Print the transformed data\nprint(X_normalized)"}]},{"title":"Encoding Categorical Features","body":["Categorical features need to be encoded into numerical values before they can be used in machine learning algorithms. We can use the OrdinalEncoder and OneHotEncoder from scikit-learn to encode categorical features."],"code":[{"lang":"python","text":"from sklearn.preprocessing import OrdinalEncoder, OneHotEncoder\nimport numpy as np\n\n# Create a sample dataset\nX = [['male', 'from US', 'uses Safari'],\n     ['female', 'from Europe', 'uses Firefox']]\n\n# Initialize the OrdinalEncoder\nordinal_encoder = OrdinalEncoder()\n\n# Fit and transform the training data\nX_encoded = ordinal_encoder.fit_transform(X)\n\n# Print the transformed data\nprint(X_encoded)\n\n# Initialize the OneHotEncoder\nonehot_encoder = OneHotEncoder()\n\n# Fit and transform the training data\nX_onehot = onehot_encoder.fit_transform(X)\n\n# Print the transformed data\nprint(X_onehot.toarray())"}]},{"title":"Imputation of Missing Values","body":["Missing values in a dataset can cause issues with machine learning algorithms. We can use the methods provided in scikit-learn's impute module to handle missing values. Here, we will use the SimpleImputer to impute missing values."],"code":[{"lang":"python","text":"from sklearn.impute import SimpleImputer\nimport numpy as np\n\n# Create a sample dataset with missing values\nX = np.array([[1., 2., np.nan],\n              [3., np.nan, 5.],\n              [np.nan, 4., 6.]])\n\n# Initialize the SimpleImputer\nimputer = SimpleImputer()\n\n# Fit and transform the training data\nX_imputed = imputer.fit_transform(X)\n\n# Print the transformed data\nprint(X_imputed)"}]},{"title":"Generating Polynomial Features","body":["Generating Polynomial Features","Sometimes it is beneficial to add complexity to a model by considering nonlinear features of the input data. We can use the PolynomialFeatures from scikit-learn to generate polynomial features."],"code":[{"lang":"python","text":"from sklearn.preprocessing import PolynomialFeatures\nimport numpy as np\n\n# Create a sample dataset\nX = np.array([[0, 1],\n              [2, 3],\n              [4, 5]])\n\n# Initialize the PolynomialFeatures\npoly = PolynomialFeatures(2)\n\n# Fit and transform the training data\nX_poly = poly.fit_transform(X)\n\n# Print the transformed data\nprint(X_poly)"}]},{"title":"Creating Custom Transformers","body":["In some cases, we may want to convert an existing Python function into a transformer to assist in data cleaning or processing. We can achieve this using the FunctionTransformer from scikit-learn."],"code":[{"lang":"python","text":"from sklearn.preprocessing import FunctionTransformer\nimport numpy as np\n\n# Create a custom function\ndef custom_function(X):\n    return np.log1p(X)\n\n# Initialize the FunctionTransformer\ntransformer = FunctionTransformer(custom_function)\n\n# Create a sample dataset\nX = np.array([[0, 1],\n              [2, 3]])\n\n# Transform the data using the custom function\nX_transformed = transformer.transform(X)\n\n# Print the transformed data\nprint"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from sklearn.preprocessing import FunctionTransformer\nimport numpy as np\n\n# Create a custom function\ndef custom_function(X):\n    return np.log1p(X)\n\n# Initialize the FunctionTransformer\ntransformer = FunctionTransformer(custom_function)\n\n# Create a sample dataset\nX = np.array([[0, 1],\n              [2, 3]])\n\n# Transform the data using the custom function\nX_transformed = transformer.transform(X)\n\n# Print the transformed data\nprint"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-imputation-of-missing-values":{"intro":"Many real-world datasets contain missing values, which can cause issues when using machine learning algorithms that assume complete and numerical data. In such cases, it is important to handle missing values appropriately to make the most of the available data. One common strategy is imputation, which involves filling in the missing values based on the known part of the data.","steps":[{"title":"Import the necessary modules","body":["First, we need to import the required modules from the scikit-learn library. We will use the SimpleImputer class for univariate feature imputation and the IterativeImputer class for multivariate feature imputation."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.impute import SimpleImputer, IterativeImputer"}]},{"title":"Univariate feature imputation using SimpleImputer","body":["Univariate feature imputation using SimpleImputer","The SimpleImputer class provides basic strategies for imputing missing values in a univariate manner. We can choose from different strategies, such as replacing missing values with a constant value or using the mean, median, or most frequent value of each column to impute the missing values.","Let's start by considering the mean strategy. We will create an instance of SimpleImputer and fit it on our data to learn the imputation strategy. Then, we can use the transform method to impute the missing values based on the learned strategy."],"code":[{"lang":"python","text":"imp = SimpleImputer(strategy='mean')\nX = [[1, 2], [np.nan, 3], [7, 6]]\nimp.fit(X)\nX_test = [[np.nan, 2], [6, np.nan], [7, 6]]\nimputed_X_test = imp.transform(X_test)"}]},{"title":"Multivariate feature imputation using IterativeImputer","body":["Multivariate feature imputation using IterativeImputer","The IterativeImputer class is a more advanced approach to imputing missing values. It models each feature with missing values as a function of other features and uses that estimate for imputation. It iteratively learns the relationships between features and imputes the missing values based on these relationships."],"code":[{"lang":"python","text":"imp = IterativeImputer()\nX = [[1, 2], [3, 6], [4, 8], [np.nan, 3], [7, np.nan]]\nimp.fit(X)\nX_test = [[np.nan, 2], [6, np.nan], [np.nan, 6]]\nimputed_X_test = imp.transform(X_test)"}]},{"title":"Nearest neighbors imputation using KNNImputer","body":["Nearest neighbors imputation using KNNImputer","The KNNImputer class provides imputation for filling in missing values using the k-Nearest Neighbors approach. It finds the nearest neighbors for each sample with missing values and imputes the missing feature values based on the values of the neighbors."],"code":[{"lang":"python","text":"from sklearn.impute import KNNImputer\nnan = np.nan\nX = [[1, 2, nan], [3, 4, 3], [nan, 6, 5], [8, 8, 7]]\nimputer = KNNImputer(n_neighbors=2)\nimputed_X = imputer.fit_transform(X)"}]},{"title":"Keeping the number of features constant","body":["Keeping the number of features constant","By default, scikit-learn imputers drop columns containing only missing values. However, in some cases, it is necessary to keep the empty features to maintain the shape of the data. We can achieve this by setting the keep_empty_features parameter to True."],"code":[{"lang":"python","text":"imputer = SimpleImputer(keep_empty_features=True)\nX = np.array([[np.nan, 1], [np.nan, 2], [np.nan, 3]])\nimputed_X = imputer.fit_transform(X)"}]},{"title":"Marking imputed values using MissingIndicator","body":["Marking imputed values using MissingIndicator","The MissingIndicator transformer is useful for indicating the presence of missing values in a dataset. It can be used in conjunction with imputation to preserve information about which values were imputed. This transformer returns a binary matrix indicating the presence of missing values in the dataset."],"code":[{"lang":"python","text":"from sklearn.impute import MissingIndicator\nX = np.array([[-1, -1, 1, 3], [4, -1, 0, -1], [8, -1, 1, 0]])\nindicator = MissingIndicator()\nmask_missing_values_only = indicator.fit_transform(X)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from sklearn.impute import MissingIndicator\nX = np.array([[-1, -1, 1, 3], [4, -1, 0, -1], [8, -1, 1, 0]])\nindicator = MissingIndicator()\nmask_missing_values_only = indicator.fit_transform(X)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-random-projection-dimensionality-reduction":{"intro":"In this lab, we will explore random projection in dimensionality reduction using the scikit-learn library. Random projection is a technique that can be used to reduce the dimensionality of data while preserving the pairwise distances between samples. This can be useful for speeding up computations and reducing memory usage in machine learning algorithms.","steps":[{"title":"Import the required libraries","body":["Let's start by importing the required libraries for this lab."],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn import random_projection"}]},{"title":"Generate random data","body":["Next, let's generate some random data that we can use for dimensionality reduction.","Here, we generate a 2D array X with 100 samples and 10,000 features. This will be our original high-dimensional data."],"code":[{"lang":"python","text":"X = np.random.rand(100, 10000)"}]},{"title":"Gaussian random projection","body":["Now, let's apply Gaussian random projection to reduce the dimensionality of our data.","In this step, we create an instance of the GaussianRandomProjection class and fit it to our data X. Then, we apply the transformation by calling the fit_transform method. The result is stored in the X_new variable."],"code":[{"lang":"python","text":"transformer = random_projection.GaussianRandomProjection()\nX_new = transformer.fit_transform(X)"}]},{"title":"Sparse random projection","body":["Next, let's try another type of random projection called sparse random projection.","Here, we create an instance of the SparseRandomProjection class and apply it to our data X using the fit_transform method. The result is stored in the X_new variable."],"code":[{"lang":"python","text":"transformer = random_projection.SparseRandomProjection()\nX_new = transformer.fit_transform(X)"}]},{"title":"Inverse transform","body":["Random projection transformers have an option to compute the inverse of the projection matrix. Let's explore this feature by applying the inverse transform to our projected data.","In this step, we create an instance of the SparseRandomProjection class with the compute_inverse_components parameter set to True. Then, we fit the transformer to our data X and apply the transformation. Finally, we compute the inverse transform by calling the inverse_transform method on the projected data X_new."],"code":[{"lang":"python","text":"transformer = random_projection.SparseRandomProjection(compute_inverse_components=True)\nX_new = transformer.fit_transform(X)\n\n# Compute the inverse transform\nX_new_inversed = transformer.inverse_transform(X_new)"}]},{"title":"Verification","body":["To verify the correctness of the inverse transform, we can compare the original data X with the result of the inverse transform.","Here, we apply the transform to the inverse transformed data X_new_inversed and check if it is equal to the original projected data X_new using the np.allclose function."],"code":[{"lang":"python","text":"X_new_again = transformer.transform(X_new_inversed)\nnp.allclose(X_new, X_new_again)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"X_new_again = transformer.transform(X_new_inversed)\nnp.allclose(X_new, X_new_again)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-kernel-approximation-techniques-in-scikit-le":{"intro":"This tutorial will guide you through the process of using kernel approximation techniques in scikit-learn.","steps":[{"title":"Nystroem Method for Kernel Approximation","body":["Nystroem Method for Kernel Approximation","The Nystroem method is a general technique for approximating kernels using a low-rank approximation. It subsamples the dataset on which the kernel is evaluated. By default, it uses the RBF kernel, but it can be used with any kernel function or a precomputed kernel matrix.","To use the Nystroem method for kernel approximation, follow these steps:","• Initialize the Nystroem object with the desired number of components (i.e., the target dimensionality of the feature transform)."],"code":[{"lang":"python","text":"from sklearn.kernel_approximation import Nystroem\n\nn_components = 100\nnystroem = Nystroem(n_components=n_components)"},{"lang":"python","text":"nystroem.fit(X_train)"},{"lang":"python","text":"X_train_transformed = nystroem.transform(X_train)\nX_test_transformed = nystroem.transform(X_test)"}]},{"title":"Radial Basis Function (RBF) Kernel Approximation","body":["Radial Basis Function (RBF) Kernel Approximation","The RBFSampler class implements an approximate mapping for the RBF kernel, also known as Random Kitchen Sinks. This technique allows us to explicitly model a kernel map before applying a linear algorithm, such as linear SVM or logistic regression.","To use RBFSampler for kernel approximation, follow these steps:","• Initialize the RBFSampler object with the desired value of gamma (the parameter of the RBF kernel) and the number of components."],"code":[{"lang":"python","text":"from sklearn.kernel_approximation import RBFSampler\n\ngamma = 0.1\nn_components = 100\nrbf_sampler = RBFSampler(gamma=gamma, n_components=n_components)"},{"lang":"python","text":"rbf_sampler.fit(X_train)"},{"lang":"python","text":"X_train_transformed = rbf_sampler.transform(X_train)\nX_test_transformed = rbf_sampler.transform(X_test)"}]},{"title":"Additive Chi Squared (ACS) Kernel Approximation","body":["Additive Chi Squared (ACS) Kernel Approximation","The ACS kernel is a kernel on histograms, commonly used in computer vision. The AdditiveChi2Sampler class provides an approximate mapping for this kernel.","To use AdditiveChi2Sampler for kernel approximation, follow these steps:","• Initialize the AdditiveChi2Sampler object with the desired number of samples (n) and the regularization parameter (c)."],"code":[{"lang":"python","text":"from sklearn.kernel_approximation import AdditiveChi2Sampler\n\nn_samples = 1000\nc = 1.0\nadditive_chi2_sampler = AdditiveChi2Sampler(n_samples=n_samples, sample_steps=2, sample_interval=2, sample_octave=2, c=c)"},{"lang":"python","text":"additive_chi2_sampler.fit(X_train)"},{"lang":"python","text":"X_train_transformed = additive_chi2_sampler.transform(X_train)\nX_test_transformed = additive_chi2_sampler.transform(X_test)"}]},{"title":"Skewed Chi Squared (SCS) Kernel Approximation","body":["Skewed Chi Squared (SCS) Kernel Approximation","The SCS kernel is a variant of the exponentiated chi squared kernel that allows for a simple Monte Carlo approximation of the feature map. The SkewedChi2Sampler class provides an approximate mapping for this kernel.","To use SkewedChi2Sampler for kernel approximation, follow these steps:","• Initialize the SkewedChi2Sampler object with the desired number of samples (n) and the regularization parameter (c)."],"code":[{"lang":"python","text":"from sklearn.kernel_approximation import SkewedChi2Sampler\n\nn_samples = 1000\nc = 1.0\nskewed_chi2_sampler = SkewedChi2Sampler(n_samples=n_samples, sample_steps=2, sample_interval=2, sample_octave=1, c=c)"},{"lang":"python","text":"skewed_chi2_sampler.fit(X_train)"},{"lang":"python","text":"X_train_transformed = skewed_chi2_sampler.transform(X_train)\nX_test_transformed = skewed_chi2_sampler.transform(X_test)"}]},{"title":"Polynomial Kernel Approximation via Tensor Sketch","body":["Polynomial Kernel Approximation via Tensor Sketch","The Polynomial kernel is a popular kernel function that models interactions between features. The PolynomialCountSketch class provides a scalable method for approximating this kernel using the TensorSketch approach.","To use PolynomialCountSketch for kernel approximation, follow these steps:","• Initialize the PolynomialCountSketch object with the desired degree (d) and the number of components."],"code":[{"lang":"python","text":"from sklearn.kernel_approximation import PolynomialCountSketch\n\ndegree = 3\nn_components = 100\npolynomial_count_sketch = PolynomialCountSketch(degree=degree, n_components=n_components)"},{"lang":"python","text":"polynomial_count_sketch.fit(X_train)"},{"lang":"python","text":"X_train_transformed = polynomial_count_sketch.transform(X_train)\nX_test_transformed = polynomial_count_sketch.transform(X_test)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"X_train_transformed = polynomial_count_sketch.transform(X_train)\nX_test_transformed = polynomial_count_sketch.transform(X_test)"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-pairwise-metrics-and-kernels-in-scikit-learn":{"intro":"In this lab, we will explore the sklearn.metrics.pairwise submodule in scikit-learn. This module provides utilities for calculating pairwise distances and affinities between sets of samples.","steps":[{"title":"Distance Metrics","body":["Distance metrics are functions that measure the dissimilarity between two objects. These metrics satisfy certain conditions, such as non-negativity, symmetry, and the triangle inequality.","Some popular distance metrics include Euclidean distance, Manhattan distance, and Minkowski distance.","Let's calculate the pairwise distances between two sets of samples using the pairwise_distances function:"],"code":[{"lang":"python","text":"import numpy as np\nfrom sklearn.metrics import pairwise_distances\n\nX = np.array([[2, 3], [3, 5], [5, 8]])\nY = np.array([[1, 0], [2, 1]])\n\n# Calculate pairwise distances between X and Y\ndistances = pairwise_distances(X, Y, metric='manhattan')\nprint(distances)"},{"lang":"text","text":"array([[4., 2.],\n       [7., 5.],\n       [12., 10.]])"}]},{"title":"Kernels","body":["Kernels are measures of similarity between two objects. They can be used in various machine learning algorithms to capture non-linear relationships between features.","Scikit-learn provides different kernel functions, such as linear kernel, polynomial kernel, sigmoid kernel, RBF kernel, Laplacian kernel, and chi-squared kernel.","Let's calculate the pairwise kernels between two sets of samples using the pairwise_kernels function:"],"code":[{"lang":"python","text":"from sklearn.metrics.pairwise import pairwise_kernels\n\nX = np.array([[2, 3], [3, 5], [5, 8]])\nY = np.array([[1, 0], [2, 1]])\n\n# Calculate pairwise kernels between X and Y using linear kernel\nkernels = pairwise_kernels(X, Y, metric='linear')\nprint(kernels)"},{"lang":"text","text":"array([[ 2.,  7.],\n       [ 3., 11.],\n       [ 5., 18.]])"}]},{"title":"Cosine Similarity","body":["Cosine similarity is a measure of the similarity between two vectors. It calculates the cosine of the angle between the vectors after normalizing them.","Scikit-learn provides the cosine_similarity function to compute the cosine similarity between vectors."],"code":[{"lang":"python","text":"from sklearn.metrics.pairwise import cosine_similarity\n\nX = np.array([[2, 3], [3, 5], [5, 8]])\nY = np.array([[1, 0], [2, 1]])\n\n# Compute cosine similarity between X and Y\nsimilarity = cosine_similarity(X, Y)\nprint(similarity)"},{"lang":"text","text":"array([[0.89442719, 0.9486833 ],\n       [0.93982748, 0.99388373],\n       [0.99417134, 0.99705449]])"}]},{"title":"Polynomial Kernel","body":["The polynomial kernel calculates the similarity between two vectors by considering the interactions between their dimensions.","Scikit-learn provides the polynomial_kernel function to compute the polynomial kernel between vectors."],"code":[{"lang":"python","text":"from sklearn.metrics.pairwise import polynomial_kernel\n\nX = np.array([[2, 3], [3, 5], [5, 8]])\nY = np.array([[1, 0], [2, 1]])\n\n# Compute polynomial kernel between X and Y\nkernel = polynomial_kernel(X, Y, degree=2)\nprint(kernel)"},{"lang":"text","text":"array([[ 10.,  20.],\n       [ 17.,  37.],\n       [ 38.,  82.]])"}]},{"title":"Summary","body":["In this lab, we explored the sklearn.metrics.pairwise submodule in scikit-learn. We learned about different pairwise metrics and kernels, their definitions, and how to use them to calculate distances and affinities between samples.","Using the pairwise_distances function, we calculated the pairwise distances between sets of samples. Using the pairwise_kernels function, we computed the pairwise kernels between sets of samples using various kernel functions.","We also explored the cosine_similarity function to calculate the cosine similarity between vectors, and the polynomial_kernel function to compute the polynomial kernel.","These pairwise metrics and kernels are useful in various machine learning tasks, such as clustering, dimensionality reduction, and similarity-based analysis."],"code":[]}],"commands":[],"reference":[],"source":"scikit-learn/scikit-learn · BSD 3-Clause"},"labex-sklearn-transforming-the-prediction-target":{"intro":"In machine learning, it is often necessary to transform the prediction target before training a model. This can include tasks such as converting multiclass labels into a binary indicator matrix or encoding non-numerical labels into numerical labels.","steps":[{"title":"Label Binarization","body":["Label binarization is the process of converting multiclass labels into a binary indicator matrix. It can be achieved using the LabelBinarizer class."],"code":[{"lang":"python","text":"from sklearn import preprocessing\n\n# Create a LabelBinarizer instance\nlb = preprocessing.LabelBinarizer()\n\n# Fit the LabelBinarizer on a list of multiclass labels\nlb.fit([1, 2, 6, 4, 2])\n\n# Get the classes learned by the LabelBinarizer\nlb.classes_\n\n# Transform a list of multiclass labels into a binary indicator matrix\nlb.transform([1, 6])"}]},{"title":"MultiLabel Binarization","body":["MultiLabel binarization is the process of converting a collection of collections of labels into an indicator format. This can be achieved using the MultiLabelBinarizer class."],"code":[{"lang":"python","text":"from sklearn.preprocessing import MultiLabelBinarizer\n\n# Define a list of collections of labels\ny = [[2, 3, 4], [2], [0, 1, 3], [0, 1, 2, 3, 4], [0, 1, 2]]\n\n# Create a MultiLabelBinarizer instance and fit_transform the list of collections\nMultiLabelBinarizer().fit_transform(y)"}]},{"title":"Label Encoding","body":["Label encoding is the process of converting non-numerical labels into numerical labels. This can be achieved using the LabelEncoder class."],"code":[{"lang":"python","text":"from sklearn import preprocessing\n\n# Create a LabelEncoder instance\nle = preprocessing.LabelEncoder()\n\n# Fit the LabelEncoder on a list of non-numerical labels\nle.fit([\"paris\", \"paris\", \"tokyo\", \"amsterdam\"])\n\n# Get the classes learned by the LabelEncoder\nlist(le.classes_)\n\n# Transform a list of non-numerical labels into numerical labels\nle.transform([\"tokyo\", \"tokyo\", \"paris\"])\n\n# Inverse transform numerical labels back to non-numerical labels\nlist(le.inverse_transform([2, 2, 1]))"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from sklearn import preprocessing\n\n# Create a LabelEncoder instance\nle = preprocessing.LabelEncoder()\n\n# Fit the LabelEncoder on a list of non-numerical labels\nle.fit([\"paris\", \"paris\", \"tokyo\", \"amsterdam\"])\n\n# Get the classes learned by the LabelEncoder\nlist(le.classes_)\n\n# Transform a list of non-numerical labels into numerical labels\nle.transform([\"tokyo\", \"tokyo\", \"paris\"])\n\n# Inverse transform numerical labels back to non-numerical labels\nlist(le.inverse_transform([2, 2, 1]))"}],"source":"scikit-learn/scikit-learn · BSD 3-Clause"}};
